<script lang="ts">import{onMount}from'svelte';import{api}from'$lib/api';import type{Content}from'$lib/types';let items:Content[]=[];let title='';let body='';let error='';let notice='';async function load(){try{items=await api<Content[]>('/api/news');}catch(e){error=e instanceof Error?e.message:'Could not load news.';}}async function create(){try{await api('/api/news',{method:'POST',body:JSON.stringify({title,body})});title='';body='';notice='News draft saved.';await load();}catch(e){error=e instanceof Error?e.message:'Could not save news.';}}async function publish(id:string){try{await api(`/api/news/${id}/publish`,{method:'POST'});notice='News post published.';await load();}catch(e){error=e instanceof Error?e.message:'Could not publish news.';}}onMount(load);</script>
<div class="toolbar"><div><span class="eyebrow">PUBLIC CONTENT</span><h2>News</h2></div></div>{#if error}<div class="error">{error}</div>{/if}{#if notice}<div class="status">{notice}</div>{/if}<section class="card"><h3>New news draft</h3><form class="form-grid" on:submit|preventDefault={create}><label class="full">Title<input bind:value={title} required /></label><label class="full">Body<textarea bind:value={body} required></textarea></label><div class="full"><button class="button">Save draft</button></div></form></section><section class="card"><h3>News queue</h3>{#each items as item}<article class="announcement"><div class="toolbar"><div><h3>{item.title}</h3><span class="pill">{item.status}</span></div>{#if item.status!=='Published'}<button class="button small-button" on:click={()=>publish(item.id)}>Publish</button>{/if}</div><p>{item.body}</p></article>{:else}<p class="muted">No news posts yet.</p>{/each}</section>
